page,svg,SITE=shared['page'],shared['svg'],shared['SITE']

wire=svg('''<defs><marker id="wire-arrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#739474" stroke-width="1.5"/></marker></defs><g fill="none" stroke="#9caf96" stroke-width="1.6"><circle cx="105" cy="100" r="62"/><circle cx="105" cy="100" r="43"/><circle cx="295" cy="100" r="62"/><circle cx="295" cy="100" r="43"/></g><path d="M167 100A62 62 0 0 0 105 38M233 100A62 62 0 0 1 295 38" fill="none" stroke="#739474" stroke-width="2" marker-end="url(#wire-arrow)"/><g fill="#fcfcf5" stroke="#b27c4e" stroke-width="2"><circle cx="105" cy="100" r="15"/><circle cx="295" cy="100" r="15"/></g><circle cx="105" cy="100" r="5" fill="#b27c4e"/><path d="M289 94L301 106M301 94L289 106" stroke="#b27c4e" stroke-width="2"/><g font-family="sans-serif" font-size="13" text-anchor="middle" fill="#5b725b"><text x="105" y="193">Strom zu dir: ⊙</text><text x="295" y="193">Strom von dir weg: ⊗</text></g>''',label='Drahtquerschnitte: Beim Punkt fließt Strom aus dem Bild, das Feld dreht gegen den Uhrzeigersinn. Beim Kreuz fließt er hinein, das Feld dreht im Uhrzeigersinn.')
cross=svg('''<defs><marker id="field-arrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#4c815a" stroke-width="1.5"/></marker></defs><g id="field-lines" fill="none" stroke="#6f996c" stroke-width="1.7"><path d="M80 130H320" marker-end="url(#field-arrow)"/><path d="M80 155H320" marker-end="url(#field-arrow)"/><path d="M80 180H320" marker-end="url(#field-arrow)"/><path d="M320 155C395 10 5 10 80 155" marker-end="url(#field-arrow)"/><path d="M320 155C395 300 5 300 80 155" marker-end="url(#field-arrow)"/></g><rect id="svg-core" x="85" y="120" width="230" height="70" rx="7" fill="#7c927a" opacity="0"/><g id="cross-top" fill="#b27c4e" font-family="sans-serif" font-size="27" text-anchor="middle">'''+''.join(f'<text x="{x}" y="109">⊙</text>' for x in range(105,310,40))+'''</g><g id="cross-bottom" fill="#b27c4e" font-family="sans-serif" font-size="27" text-anchor="middle">'''+''.join(f'<text x="{x}" y="228">⊗</text>' for x in range(105,310,40))+'''</g><text id="pole-left" x="34" y="163" fill="#6d8d9b" font-size="22" font-family="sans-serif">S</text><text id="pole-right" x="350" y="163" fill="#b27650" font-size="22" font-family="sans-serif">N</text>''','0 0 400 310','Spule im Schnitt: oben tritt Strom aus dem Bild, unten hinein. Das Magnetfeld zeigt innen nach rechts zum Nordpol, außen zurück zum Südpol.')

tasks=[
('Spannung bestimmen','Durch die Spule mit R = 3 Ω fließen 0,5 A. Welche Spannung liegt an?','V',1.5,['Gesucht: U. Gegeben: R = 3 Ω, I = 0,5 A.','U = R · I','U = 3 Ω · 0,5 A = 1,5 V.'],'Multipliziere Widerstand und Stromstärke.'),
('Stromstärke berechnen','An R = 3 Ω liegen 1,8 V an. Wie groß ist die Stromstärke?','A',0.6,['I = U / R','I = 1,8 V / 3 Ω','I = 0,6 A. Der Wert liegt unter 1 A.'],'Stelle U = R · I nach I um: I = U / R.'),
('Den Widerstand finden','Bei U = 2,4 V fließen I = 0,8 A. Berechne R.','Ω',3,['R = U / I','R = 2,4 V / 0,8 A','R = 3 Ω.'],'Teile die Spannung durch die Stromstärke.'),
('Die Stromgrenze einhalten','Im Gleichstrommodell hat die Spule R = 3 Ω und darf höchstens I = 1 A führen. Welche Spannung ergibt sich an dieser Grenze?','V',3,['U = R · I','U = 3 Ω · 1 A = 3 V.','Das ist eine Modellrechnung, keine allgemeine Betriebsspannungsfreigabe.'],'Nutze die maximale Stromstärke in U = R · I.'),
('Doppelt so viele Windungen','Zwei lange Luftspulen sind gleich lang. Spule A hat 400 Windungen, Spule B hat 800. Durch beide fließt derselbe Strom. Wie vielmal so groß ist B bei Spule B?','fach',2,['Bei gleicher Länge und Stromstärke gilt B ∝ N.','Verhältnis = 800 / 400','Das Magnetfeld ist 2-mal so groß.'],'Vergleiche 800 Windungen mit 400 Windungen.'),
('Zwei Änderungen auf einmal','Bei gleicher Länge: Eine Luftspule wechselt von 400 Windungen und 0,5 A zu 600 Windungen und 1 A. Um welchen Faktor wächst B?','fach',3,['B₂ / B₁ = (N₂ · I₂) / (N₁ · I₁)','= (600 · 1) / (400 · 0,5)','= 600 / 200 = 3.'],'Multipliziere den Windungsfaktor 600/400 mit dem Stromfaktor 1/0,5.'),
('Elektrische Leistung','An der Spule liegen 3 V an, es fließt 1 A. Welche Leistung nimmt sie im stationären Gleichstromfall auf?','W',3,['P = U · I','P = 3 V · 1 A','P = 3 W. Im stationären Fall wird diese Leistung am Drahtwiderstand in Wärme umgesetzt.'],'Leistung ist Spannung mal Stromstärke.'),
('Bonus: Energie im Magnetfeld','Eine Spule mit konstanter Induktivität L = 3 mH führt I = 1 A. Wie viel Energie ist gespeichert? Gib sie in mJ an.','mJ',1.5,['L = 3 mH = 0,003 H.','E = ½ · L · I² = 0,5 · 0,003 H · (1 A)²','E = 0,0015 J = 1,5 mJ.'],'Zuerst mH in H umrechnen. Das Ergebnis in Joule anschließend mal 1000 nehmen.')
]
exercise_html=''
for i,(title,prompt,unit,answer,steps,hint) in enumerate(tasks,1):
    exercise_html+=f'''<article class="exercise" data-answer="{answer}" data-unit="{unit}"><span class="section-number">Aufgabe {i:02}</span><h3>{title}</h3><p>{prompt}</p><form class="answer-row"><label for="answer-{i}">Ergebnis</label><input id="answer-{i}" type="text" inputmode="decimal" autocomplete="off" aria-describedby="feedback-{i}"><span>{unit}</span><button type="submit">Prüfen</button></form><p class="feedback" id="feedback-{i}" aria-live="polite"></p><details><summary>Ein kleiner Tipp</summary><p>{hint}</p></details><details class="solution"><summary>Lösungsweg ansehen</summary><ol>{''.join(f'<li>{s}</li>' for s in steps)}</ol></details></article>'''

body=f"""<main id="main" class="wrap"><div class="crumbs"><a href="/">Lerninhalte</a> / <a href="/#physik">Physik</a> / Spule & Elektromagnet</div><section class="lesson-hero"><p class="eyebrow">Physik · Elektrizität & Magnetismus</p><h1>Ein Draht. Viele Windungen.<br><em>Ein Magnetfeld.</em></h1><p class="lead">Warum wird eine Spule magnetisch, wenn Strom durch sie fließt? Schau es dir in 3D an, verändere das Modell und rechne mit den Angaben aus dem Heft.</p><div class="lesson-tags"><span>◉ 3D-Modell & Schnittbild</span><span>↗ Schrittweise Erklärungen</span><span>✎ 8 Rechenaufgaben</span></div></section><nav class="lesson-nav" aria-label="In diesem Kapitel"><a href="#grundidee">01 Grundidee</a><a href="#spulenlabor">02 Spulenlabor</a><a href="#eisenkern">03 Eisenkern</a><a href="#rechnen">04 Rechnen verstehen</a><a href="#uebungen">05 Selbst üben</a></nav><noscript><p class="no-js">Die Erklärungen, Zeichnungen und Lösungswege funktionieren ohne JavaScript. Für das 3D-Modell und die Antwortprüfung aktiviere JavaScript.</p></noscript>
<section class="lesson-section" id="grundidee"><span class="section-number">01 · Vom Draht zur Spule</span><h2>Viele kleine Felder wirken zusammen.</h2><p class="section-intro">Um einen stromdurchflossenen Draht entsteht ein Magnetfeld. Wickelst du den Draht zur Spule, überlagern sich die Felder der einzelnen Windungen.</p><div class="two-col"><article class="panel"><div class="diagram">{wire}</div><h3>Ein Draht: kreisförmige Feldlinien</h3><p>Der Punkt ⊙ ist wie eine Pfeilspitze: Der Strom kommt zu dir. Das Kreuz ⊗ ist wie das Ende eines Pfeils: Der Strom fließt von dir weg.</p><p><strong>Rechte-Faust-Regel:</strong> Der Daumen zeigt in die technische Stromrichtung, die gekrümmten Finger zeigen die Feldrichtung. Die Elektronen bewegen sich entgegengesetzt zur technischen Stromrichtung.</p></article><article class="panel"><div class="diagram">{shared['coil']}</div><h3>Eine Spule: ein gemeinsames Feld</h3><p>Im Inneren unterstützen sich die Magnetfelder. Bei einer langen, eng gewickelten Spule sind die Feldlinien dort fast parallel. Das Feld ist in der Mitte annähernd gleich stark.</p><p>Die Spule hat einen Nord- und einen Südpol. Außen zeigen die Feldlinien von Nord nach Süd, innen von Süd nach Nord. Sie bilden geschlossene Linien.</p></article></div><div class="callout"><p><strong>Merke:</strong> Mehr Windungen pro Länge und mehr Strom ergeben ein stärkeres Magnetfeld. Beim Vergleich müssen Spulenlänge und Kern gleich bleiben. Die Stärke des Feldes ist nicht dasselbe wie die Kraft auf einen beliebigen Gegenstand.</p></div></section>
<section class="lesson-section" id="spulenlabor"><span class="section-number">02 · Sehen, was sich verändert</span><h2>Dein kleines Spulenlabor.</h2><p class="section-intro">Ziehe an der Spule, um sie zu drehen. Probiere dann: Strom verdoppeln, Windungszahl erhöhen, Stromrichtung umkehren. Welche Eigenschaften ändern sich?</p><div class="simulation"><div class="sim-heading"><h3>Strom an. Feld sichtbar.</h3><div class="view-buttons" role="group" aria-label="Ansicht wählen"><button id="view-3d" aria-pressed="false" type="button">3D-Modell</button><button id="view-2d" aria-pressed="true" type="button">Schnittbild</button></div></div><div class="sim-body"><div class="sim-stage"><div class="sim-3d" id="model" hidden><p class="loading-3d">Das 3D-Modell wird geladen …</p><span class="sim-hint">Ziehen zum Drehen · Pfeiltasten bei fokussiertem Modell · Feldlinien schematisch</span></div><div class="sim-2d" id="cross-section">{cross}</div><div class="schematic-legend"><span>⊙ Strom zu dir</span><span>⊗ Strom von dir weg</span></div></div><div class="controls"><label class="control" for="current"><span>Stromstärke I <output id="current-value">0,5 A</output></span><input id="current" type="range" min="0" max="1" step="0.1" value="0.5"></label><label class="control" for="turns"><span>Windungszahl N <output id="turns-value">400</output></span><input id="turns" type="range" min="200" max="800" step="100" value="400"></label><label class="check-control"><input id="core" type="checkbox"> Eisenkern einsetzen</label><label class="check-control"><input id="reverse" type="checkbox"> Stromrichtung umkehren</label><label class="check-control"><input id="pause" type="checkbox"> Animation pausieren</label><div class="sim-result" aria-live="polite"><span id="ratio-label">Feld im Vergleich zum Start</span><strong id="field-value">1,0-fach</strong><span id="field-note">Luftspule, gleiche Länge.</span></div></div></div><div class="sim-explanation"><p id="model-description">400 Windungen, 0,5 A: Innen zeigt das Feld nach rechts, rechts ist der Nordpol.</p><p>Die gezeichneten Windungen stehen stellvertretend für N. Leuchtpunkte markieren die Feldrichtung, keine fliegenden Teilchen. Die Darstellung ist kein berechnetes räumliches Feld. Ohne Strom verschwindet hier das Spulenfeld; eine mögliche Restmagnetisierung des Eisenkerns wird nicht dargestellt.</p></div></div><div class="knowledge" style="margin-top:24px"><article class="panel"><h3>Mehr Strom</h3><p>Doppelter Strom führt bei einer Luftspule näherungsweise zur doppelten magnetischen Flussdichte B.</p></article><article class="panel"><h3>Mehr Windungen</h3><p>Bei gleicher Länge verstärkt die doppelte Windungszahl das Feld auf das Doppelte. Die Stromstärke muss gleich bleiben.</p></article><article class="panel"><h3>Andere Stromrichtung</h3><p>Die Feldrichtung kehrt sich um. Nord- und Südpol tauschen ihre Seiten; der Betrag von B bleibt bei gleichem Strombetrag gleich.</p></article></div></section>
<section class="lesson-section" id="eisenkern"><span class="section-number">03 · Der Elektromagnet</span><h2>Was macht der Eisenkern?</h2><div class="two-col"><article class="panel"><h3>Der Kern verstärkt das Feld.</h3><p>Im Eisen gibt es kleine magnetische Bereiche. Ohne äußeres Feld sind sie bei unmagnetisiertem Eisen unterschiedlich ausgerichtet. Das Spulenfeld richtet viele davon gleich aus: Der Kern trägt zum Gesamtfeld bei.</p><div class="diagram">{svg('''<g stroke="#8a9a7f" stroke-width="3" fill="none"><path d="M40 45L65 70L54 68M105 75V42L97 52M145 50L170 70L158 68M50 130L72 110L60 112M110 115L95 140L96 128M145 140L170 120L158 122"/></g><path d="M193 95H225L216 87M225 95L216 103" fill="none" stroke="#b29970" stroke-width="2"/><g stroke="#4e8054" stroke-width="3" fill="none"><path d="M250 55H280L271 47M280 55L271 63M310 55H340L331 47M340 55L331 63M250 95H280L271 87M280 95L271 103M310 95H340L331 87M340 95L331 103M250 135H280L271 127M280 135L271 143M310 135H340L331 127M340 135L331 143"/></g><g fill="#6b7e63" font-size="12" font-family="sans-serif" text-anchor="middle"><text x="105" y="190">ungeordnet</text><text x="298" y="190">stärker ausgerichtet</text></g>''',label='Magnetische Bereiche zeigen zuerst in verschiedene Richtungen. Im äußeren Feld sind viele gleich ausgerichtet.')}</div><p class="small">Vereinfachtes Bild magnetischer Bereiche, keine Darstellung einzelner Elektronen.</p></article><article class="panel"><h3>Eine Spule plus Eisenkern.</h3><p>So ist der Elektromagnet in deinem Heft aufgebaut. Er lässt sich über den Strom steuern. Elektromagnete können auch ohne Eisenkern gebaut werden, der Kern verstärkt die Wirkung.</p><p>Wie stark genau, hängt unter anderem vom Material, der Form, einem Luftspalt und der magnetischen Sättigung ab. Deshalb zeigt das Modell für den Kern keinen erfundenen Verstärkungsfaktor.</p><div class="callout"><p><strong>Denke an einen Schrottplatzkran:</strong> Ein Elektromagnet kann ferromagnetische Teile anziehen. Aluminium und Kupfer haften nicht wie Eisen an einem ruhenden Elektromagneten.</p></div></article></div></section>
<section class="lesson-section" id="rechnen"><span class="section-number">04 · Vom Heft zur Rechnung</span><h2>Erst die Größen. Dann die Formel.</h2><p class="section-intro">Diese vier Angaben stehen auf deinem Foto. Die Beispiele behandeln die Spule bei konstantem Gleichstrom nach dem Einschalten; R bleibt im Modell konstant. Beim Ein- und Ausschalten spielt zusätzlich die Induktivität eine Rolle.</p><div class="data-grid"><div class="data-card"><strong>400</strong><span>N · Windungszahl</span><small>Anzahl der Drahtwindungen</small></div><div class="data-card"><strong>max. 1 A</strong><span>I · Stromstärke</span><small>Stromgrenze der Heftspule</small></div><div class="data-card"><strong>3 Ω</strong><span>R · Widerstand</span><small>Elektrischer Drahtwiderstand</small></div><div class="data-card"><strong>3 mH</strong><span>L · Induktivität</span><small>3 Millihenry = 0,003 Henry</small></div></div><div class="two-col"><article class="panel"><span class="section-number">Beispiel 1 · Spannung</span><h3>Wie viel Spannung für 0,5 A?</h3><div class="formula">U = R · I</div><ol class="calc-steps"><li><span>Gegeben</span><div>R = 3 Ω, I = 0,5 A</div></li><li><span>Gesucht</span><div>Spannung U in Volt</div></li><li><span>Einsetzen</span><div>U = 3 Ω · 0,5 A</div></li><li><span>Ergebnis</span><div class="result">U = 1,5 V</div></li></ol><p>Doppelter Strom braucht im Modell bei gleichem Widerstand die doppelte Spannung.</p></article><article class="panel"><span class="section-number">Beispiel 2 · Magnetfeld vergleichen</span><h3>Was bringen 800 Windungen?</h3><div class="formula">B₂ / B₁ = N₂ / N₁</div><ol class="calc-steps"><li><span>Gleich bleibt</span><div>Stromstärke, Länge, Luftkern</div></li><li><span>Gegeben</span><div>N₁ = 400, N₂ = 800</div></li><li><span>Einsetzen</span><div>B₂ / B₁ = 800 / 400 = 2</div></li><li><span>Ergebnis</span><div class="result">Doppelte magnetische Flussdichte.</div></li></ol><p>Der allgemeine Zusammenhang für eine lange Luftspule ist B ≈ μ₀ · N · I / ℓ. Ohne Spulenlänge lässt sich aus dem Foto kein B-Wert in Tesla berechnen.</p></article></div><div class="two-col" style="margin-top:25px"><article class="panel"><span class="section-number">Beispiel 3 · Leistung</span><h3>Wo gehen die 3 Watt hin?</h3><div class="formula">P = U · I = I² · R</div><p>Bei 1 A und 3 Ω gilt: U = 3 V, also P = 3 V · 1 A = <strong>3 W</strong>. Bei stationärem Gleichstrom wird diese Leistung im Draht in Wärme umgesetzt.</p><p>Halbierst du I, sinkt die Wärmeleistung auf ein Viertel: (0,5 A)² · 3 Ω = <strong>0,75 W</strong>.</p><div class="energy-bar" aria-label="0,75 Watt sind ein Viertel von 3 Watt"><span>¼</span></div><p class="caption">Halber Strom → ein Viertel der Wärmeleistung.</p></article><article class="panel"><span class="section-number">Bonus · Induktivität</span><h3>Energie im Magnetfeld.</h3><div class="formula">E = ½ · L · I²</div><p>Für konstantes L = 3 mH = 0,003 H und I = 1 A:</p><p>E = ½ · 0,003 H · (1 A)²<br><strong class="result">E = 0,0015 J = 1,5 mJ</strong></p><p>Die gespeicherte Energie in Joule ist etwas anderes als die laufende Wärmeleistung in Watt. Für einen nichtlinearen Eisenkern ist ein konstantes L nur eine Näherung.</p></article></div><div class="callout"><p><strong>Einheiten nicht verwechseln:</strong> Ω gehört zum Widerstand, H zur Induktivität. 3 mH sind nicht 3 Ω. Die Stromgrenze aus dem Heft gilt für die reale Spule; die Beispielrechnungen ersetzen keine Angaben zum sicheren Betrieb oder zur Erwärmung.</p></div></section>
<section class="lesson-section" id="uebungen"><span class="section-number">05 · Jetzt du</span><h2>Einsetzen. Rechnen. Prüfen.</h2><p class="section-intro">Nutze Komma oder Punkt als Dezimalzeichen. Die Einheit steht neben dem Eingabefeld. Falls du festhängst, öffne erst den Tipp und dann den Lösungsweg.</p><p class="progress-label" aria-live="polite"><span id="task-progress">0 von 8</span> richtig gelöst · nur für diesen Seitenbesuch</p><div class="exercise-grid">{exercise_html}</div></section>
<section class="lesson-section"><span class="section-number">Zum Schluss · Drei Denkfragen</span><h2>Kannst du es erklären?</h2><div class="knowledge"><article class="panel"><h3>Hat eine Spule ohne Eisenkern ein Magnetfeld?</h3><details><summary>Antwort ansehen</summary><p>Ja, wenn Strom fließt. Der Eisenkern verstärkt das Feld, er ist nicht dessen Voraussetzung.</p></details></article><article class="panel"><h3>Wird beim Umpolen das Magnetfeld schwächer?</h3><details><summary>Antwort ansehen</summary><p>Bei gleichem Strombetrag bleibt der Betrag von B gleich. Die Feldrichtung und die Pole wechseln.</p></details></article><article class="panel"><h3>Was gilt bei doppelter Länge und doppelter Windungszahl?</h3><details><summary>Antwort ansehen</summary><p>Bei gleichem Strom und Luftkern bleibt N/ℓ gleich. Im Modell der langen Spule bleibt deshalb auch B gleich.</p></details></article></div></section>
<div class="section-end"><a class="button light" href="/#physik">← Zur Lernübersicht</a><button class="print-button" id="print" type="button">Kapitel & Aufgaben drucken</button></div><aside class="sources"><p><strong>Grundlage:</strong> Deine Heftnotiz zu Spule und Elektromagnet. Zeichnungen, 3D-Modell und Aufgaben wurden für dieses Kapitel erstellt. Weiterführende Quellen zur fachlichen Einordnung:</p><ul><li><a href="https://www.schule-bw.de/faecher-und-schularten/mathematisch-naturwissenschaftliche-faecher/physik/unterrichtsmaterialien/e_lehre_1/elektromagnetismus/spule.htm">Landesbildungsserver Baden-Württemberg: Von der Leiterschleife zur Spule</a></li><li><a href="https://www.leifiphysik.de/elektrizitaetslehre/magnetisches-feld-spule">LEIFIphysik: Magnetisches Feld einer Spule</a></li><li><a href="https://openstax.org/books/university-physics-volume-2/pages/14-3-energy-in-a-magnetic-field">OpenStax: Energy in a Magnetic Field</a></li></ul></aside></main>"""
(SITE/'physik/spule-elektromagnet/index.html').write_text(page('Spule & Elektromagnet · Physik · school',body,'<script src="/assets/physics.js" defer></script><script type="module" src="/assets/coil-3d.js"></script>'))
